import {leads,properties,sources,records,addDays,bookTour} from './model.mjs';

export const callAgents=[...properties.map(p=>({id:'agent-'+p.id,name:p.owner,service:'Property leasing team'})),{id:'agent-contact-01',name:'Jordan Patel',service:'Central Call Center'},{id:'agent-contact-02',name:'Taylor Brooks',service:'After-hours service'}];
export const stages=[['all','Enquiries'],['scheduled','Tours scheduled'],['toured','Tours completed'],['applied','Applications'],['leased','Leases signed']];
export const channels=['Email','SMS','Phone','Web chat','WhatsApp','Visit','Note'];
export const leadTags=[['new','New'],['hot','Hot'],['warm','Warm'],['cold','Cold'],['nurture','Nurture'],['disqualified','Disqualified'],['converted','Converted']];
export const leadTagName=tag=>leadTags.find(([id])=>id===tag)?.[1]||'New';
export function leadTag(l,s){const saved=s.leadTags?.[l.id];return leadTags.some(([id])=>id===saved)?saved:l.leased?'converted':l.applied||l.toured?'hot':l.scheduled?'warm':'new';}
export function setLeadTag(s,id,tag){prepareCRM(s);if(!leads.some(l=>l.id===id))throw new Error('Choose a valid lead.');if(!leadTags.some(([key])=>key===tag))throw new Error('Choose a valid lead tag.');s.leadTags[id]=tag;return tag;}
export const stageName=l=>l.leased?'Lease signed':l.applied?'Application received':l.toured?'Tour completed':l.scheduled?'Tour scheduled':'Enquiry received';
export function prepareCRM(s){for(const k of ['interactions'])if(!Array.isArray(s[k]))s[k]=[];for(const k of ['tourDetails','prospectOwners','leadTags'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))s[k]={};return s;}
export function prospect(id,s){const raw=leads.find(l=>l.id===id);if(!raw)return null;prepareCRM(s);const n=Number(id.slice(1)),p=properties.find(p=>p.id===raw.property),l={...raw,scheduled:raw.scheduled||s.tourBookings.includes(id)};
 const tour=s.tourDetails[id]||(l.scheduled?{date:addDays(l.created,2),time:'14:00',type:n%2?'In person':'Virtual',host:p.owner,unit:String(100+n%300),notes:l.toured?'Viewed the floor plan and discussed availability.':'Appointment confirmed in the sample record.',status:l.toured?'Completed':'Scheduled'}:null);
 return {...l,tag:leadTag(l,s),contactId:'P-'+id,email:id.toLowerCase()+'@example.invalid',phone:'+1 416 555 '+String(100+n%100).padStart(4,'0'),owner:s.prospectOwners[id]||p.owner,preferredChannel:n%2?'Email':'SMS',bedrooms:n%3+1,budget:2200+n%6*150,moveIn:addDays(l.leaseDate||l.created,30),unit:String(100+n%300),campaign:sources.find(x=>x.id===l.source)?.paid?'Fall leasing · '+p.code:'Unpaid / direct',utmSource:l.source==='unknown'?'Not captured':l.source,utmMedium:['google','meta'].includes(l.source)?'cpc':l.source==='ils'?'listing':'organic / referral',tour,application:l.applied?{id:'APP-'+id,received:addDays(l.created,3),status:l.leased?'Lease completed':'In review',applicants:n%2+1,documents:[['Application form','Received'],['Identity document','Sample placeholder'],['Supporting documents',l.leased?'Received':'Requested']],note:'Fictional workflow only. No documents, screening results or eligibility decisions are stored.'}:null,lease:l.leased?{id:'LEASE-'+id,signed:l.leaseDate,start:addDays(l.leaseDate,14),end:addDays(l.leaseDate,378),rent:2200+n%6*150,term:'12 months',status:'Signed',document:'Sample lease metadata · no document attached'}:null};
}
export function seededInteractions(id){const l=leads.find(x=>x.id===id);if(!l)return [];const n=Number(id.slice(1)),owner=properties.find(p=>p.id===l.property).owner,out=[];
 const assigned=callAgents[n%5===0?4:n%5===1?5:properties.findIndex(p=>p.id===l.property)];
 const phoneOutcome=n%17===0?'Abandoned':n%13===0?'No answer':'Connected';
 const phoneAnswered=phoneOutcome==='Connected',phoneBooked=phoneAnswered&&l.scheduled&&n%2===0;
 const add=(offset,direction,channel,subject,body,extra={})=>out.push({id:`SEED-${id}-${out.length+1}`,leadId:id,contactId:'P-'+id,property:l.property,at:new Date(Date.parse(l.created+'T13:00:00Z')+offset*3600000).toISOString(),direction,channel,subject,body,agent:direction==='inbound'?l.name:owner,status:direction==='inbound'?'Demo received':'Demo sent',...extra});
 add(0,'inbound',n%2?'Web chat':'Email','Availability enquiry','I am interested in this community. Could you share available homes and pricing?');
 add(.25,'outbound','Email','Thanks for your enquiry','Thank you for contacting our leasing team. Here are the available floor plans and tour options.');
 for(let i=0;i<n%3;i++){add(3+i*2,'inbound',i?'Phone':'SMS',i?'Call about move-in timing':'Follow-up question',i?(phoneAnswered?(phoneBooked?'Discussed availability and booked a property tour.':'Asked about move-in dates and available viewing times.'):phoneOutcome==='Abandoned'?'Caller left the queue before an agent answered.':'Incoming call was not answered; follow-up required.'):'Is there availability for my preferred move-in date?',i?{duration:phoneAnswered?180+n%7*20:0,outcome:phoneOutcome,assignedAgentId:assigned.id,handledById:phoneAnswered?assigned.id:null,handledBy:phoneAnswered?assigned.name:null,waitSeconds:12+n%37,holdSeconds:phoneAnswered?15+n%4*10:0,wrapSeconds:phoneAnswered?30+n%3*15:0,tourBooked:phoneBooked}:{});add(3.5+i*2,'outbound',i?'Phone':'SMS','Leasing follow-up','Discussed availability and the next steps.',i?{duration:180,agent:assigned.name,agentId:assigned.id,assignedAgentId:assigned.id,outcome:'Connected',holdSeconds:10,wrapSeconds:30,tourBooked:false}:{});}
 if(l.scheduled)add(24,'outbound','Email','Tour confirmation','Your sample tour is confirmed. The leasing team will meet you at the office.');
 if(l.toured)add(53,'inbound','Visit','Property tour completed','Viewed the community and discussed floor plans.',{duration:1800,outcome:'Completed'});
 if(l.applied)add(72,'inbound','Email','Application submitted','The sample application has been received by the leasing team.');
 if(l.leased)add(l.days*24,'outbound','Email','Lease signed','Your sample lease has been signed. Move-in information is ready.');
 return out;
}
export function interactionHistory(id,s){prepareCRM(s);return [...seededInteractions(id),...s.interactions.filter(x=>x.leadId===id)].sort((a,b)=>b.at.localeCompare(a.at)||b.id.localeCompare(a.id));}
export function contactStats(id,s){const xs=interactionHistory(id,s).filter(x=>x.channel!=='Note'&&x.status!=='Draft');return {total:xs.length,inbound:xs.filter(x=>x.direction==='inbound').length,outbound:xs.filter(x=>x.direction==='outbound').length,channels:[...new Set(xs.map(x=>x.channel))],last:xs[0]||null};}
export function pipelineRecords(f,s,{stage='all',search='',source='all',tag='all'}={}){const q=search.trim().toLowerCase();return records(f,s).leads.filter(l=>(stage==='all'||Boolean(l[stage]))&&(source==='all'||l.source===source)).map(l=>prospect(l.id,s)).filter(l=>tag==='all'||l.tag===tag).filter(l=>!q||[l.name,l.id,l.contactId,l.email,l.phone,properties.find(p=>p.id===l.property).name].join(' ').toLowerCase().includes(q));}
export function addInteraction(s,input){prepareCRM(s);const l=prospect(input.leadId,s);if(!l)throw new Error('Choose a valid prospect.');if(!channels.includes(input.channel))throw new Error('Choose a valid channel.');if(!['inbound','outbound','internal'].includes(input.direction))throw new Error('Choose an interaction direction.');if((input.channel==='Note')!==(input.direction==='internal'))throw new Error('Internal notes must use the Note channel.');const body=String(input.body||'').trim();if(!body)throw new Error('Write a message or interaction summary.');if(body.length>5000)throw new Error('Keep the summary under 5,000 characters.');const at=input.at||new Date().toISOString();if(!Number.isFinite(Date.parse(at))||Date.parse(at)<Date.parse(l.created)||Date.parse(at)>Date.now()+60000)throw new Error('Use a valid interaction time between enquiry creation and now.');if(input.key&&s.interactions.some(x=>x.key===input.key))return s.interactions.find(x=>x.key===input.key);
 const duration=Number(input.duration||0);if(!Number.isFinite(duration)||duration<0||duration>86400)throw new Error('Enter a valid duration in seconds.');
 const event={id:'INT-'+Date.now()+'-'+s.interactions.length,leadId:l.id,contactId:l.contactId,property:l.property,at:new Date(at).toISOString(),direction:input.direction,channel:input.channel,subject:String(input.subject||'Leasing conversation').slice(0,140),body,agent:input.direction==='inbound'?l.name:l.owner,status:input.draft?'Draft':input.direction==='internal'?'Internal note':input.channel==='Phone'||input.channel==='Visit'?'Logged demo interaction':input.direction==='inbound'?'Demo received':'Demo sent',duration,outcome:input.outcome||'',key:input.key||null};if(input.channel==='Phone'){const assigned=callAgents.find(a=>a.name===l.owner);event.assignedAgentId=assigned?.id||null;event.handledById=['Connected','Completed','Follow-up required'].includes(event.outcome)?assigned?.id||null:null;event.handledBy=event.handledById?assigned.name:null;}s.interactions.push(event);s.activity.unshift({text:`${event.channel} ${event.direction} interaction recorded for ${l.name}`,kind:'Communication',time:event.at});return event;
}
export function scheduleTour(s,id,input){const l=prospect(id,s);if(!l)throw new Error('Prospect not found.');if(l.tour)throw new Error('A tour already exists for this prospect.');if(!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||!Number.isFinite(Date.parse(input.date))||input.date<new Date().toISOString().slice(0,10))throw new Error('Choose a tour date today or later.');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(input.time))throw new Error('Choose a valid tour time.');if(!['In person','Virtual'].includes(input.type))throw new Error('Choose a tour type.');const owner=properties.find(p=>p.id===l.property).owner;bookTour(s,id);s.tourDetails[id]={date:input.date,time:input.time,type:input.type,host:l.owner||owner,unit:l.unit,notes:input.notes||'',status:'Scheduled'};addInteraction(s,{leadId:id,channel:'Email',direction:'outbound',subject:'Tour confirmation',body:`Sample ${input.type.toLowerCase()} tour booked for ${input.date} at ${input.time} (property local time). ${input.notes||''}`,key:'tour-confirmation-'+id});return s.tourDetails[id];}
